'use strict'
// CP62: Excel import templates + readable import errors.
// Kinds: ACTUAL XLSX FILES (generated by the real writer, read back by the real parser) + MOCKED db connection. NOT MySQL/MariaDB.
const test = require('node:test')
const assert = require('node:assert/strict')
const path = require('node:path')
const Module = require('node:module')
// --- mocked database (answers only the SELECTs the preview needs) ---
const dbPath = path.join(__dirname, '../database/db.js')
let dbMode = 'ok'
const dbMock = { getConnection(cb) { if (dbMode === 'fail') return cb(Object.assign(new Error("ER_ACCESS_DENIED_ERROR: Access denied for user 'root'@'localhost' (SELECT * FROM users)"), { code: 'ER_ACCESS_DENIED_ERROR', sql: 'SELECT * FROM users' }))
  cb(null, { release() {}, query(sql, values, callback) { if (typeof values === 'function') { callback = values; values = [] }; const s = sql.replace(/\s+/g, ' ').trim()
    if (s.startsWith('SELECT id, laboratory_name, capacity FROM laboratories')) return callback(null, [{ id: 1, laboratory_name: 'Lab A', capacity: 50 }])
    if (s.startsWith('SELECT id, computer_name, laboratory_id FROM computers')) return callback(null, [])
    if (/^SELECT .*FROM (computers|equipment)/.test(s)) return callback(null, [])
    if (s.startsWith('SELECT category, value FROM lookup_options')) return callback(null, [])
    if (/AS k FROM/.test(s)) return callback(null, [])
    callback(new Error('unexpected sql ' + s)) } }) } }
const m = new Module(dbPath); m.filename = dbPath; m.loaded = true; m.exports = dbMock; require.cache[dbPath] = m
const { buildTemplate, SPECS, FIELD_MAPS, keyOf } = require('../utils/importTemplates.js')
const { buildWorkbook } = require('../utils/xlsxMultiSheet.js')
const { parseXlsx } = require('../utils/xlsxParser.js')
const { createExcelImportController } = require('../controllers/excelImportController.js')
const { createSimpleImportController } = require('../controllers/simpleImportController.js')
const { userFacingMessage, missingColumns } = require('../utils/importDiagnostics.js')
const { createImportTemplateController } = require('../controllers/importTemplateController.js')
const TYPES = ['users', 'laboratories', 'computers', 'equipment']
const controllerFor = type => (type === 'users' || type === 'laboratories') ? createSimpleImportController(type) : createExcelImportController(type)
const res = () => ({ code: 200, body: null, headers: {}, status(c) { this.code = c; return this }, json(b) { this.body = b; return this }, send(b) { this.body = b; return this }, setHeader(k, v) { this.headers[k] = v } })
async function preview(type, buffer, fileName = 'upload.xlsx') { const r = res(); await controllerFor(type).preview({ body: { fileName, fileBase64: buffer.toString('base64') }, user: { id: 1, role: 'MIS' } }, r); return r }

test('templates are real .xlsx files: data sheet first, then Instructions and an Examples sheet', () => {
  for (const type of TYPES) { const sheets = parseXlsx(buildTemplate(type)); const names = Object.keys(sheets)
    assert.deepEqual(names, [SPECS[type].dataSheet, 'Instructions', 'Examples (not imported)'], type) }
})
test('every template header maps to a REAL import field, all required fields are present, and "required" flags agree with the importer', () => {
  const REQUIRED = require('../utils/importDiagnostics.js').missingColumns
  for (const type of TYPES) { const headers = parseXlsx(buildTemplate(type))[SPECS[type].dataSheet][0]
    assert.deepEqual(headers, SPECS[type].columns.map(c => c.header))
    for (const h of headers) assert.ok(FIELD_MAPS[type][keyOf(h)], `${type}: header "${h}" is not an import column`)
    assert.deepEqual(REQUIRED(headers, type), [], `${type}: template lacks a required column`)
    // each declared field is the one the importer maps that header to
    for (const c of SPECS[type].columns) assert.equal(FIELD_MAPS[type][keyOf(c.header)], c.field)
    // the template's Required flags are exactly the importer's required fields (users/labs: the columns the real validators need)
    const flagged = SPECS[type].columns.filter(c => c.required).map(c => c.field).sort()
    assert.deepEqual(flagged, [...require('../utils/importDiagnostics.js').REQUIRED[type]].sort(), type) }
})
test('the untouched template contains NO data rows, so it can never import fake records by accident', async () => {
  for (const type of TYPES) { const sheets = parseXlsx(buildTemplate(type)); assert.equal(sheets[SPECS[type].dataSheet].length, 1, type)
    const r = await preview(type, buildTemplate(type)); assert.equal(r.code, 400, type); assert.match(r.body.message, /data row/i, type) }
})
test('example rows are clearly marked, live only on the non-imported sheet, and pass the REAL validators', async () => {
  for (const type of TYPES) { const ex = parseXlsx(buildTemplate(type))['Examples (not imported)']
    assert.match(ex[0][0], /EXAMPLES ONLY.*NOT IMPORTED/i); assert.ok(ex[2].some(v => /EXAMPLE/i.test(String(v))), `${type}: example row not marked`)
    // feed the example row through the real importer as if the user had pasted it into the data sheet
    const book = buildWorkbook([{ name: SPECS[type].dataSheet, rows: [ex[1], ex[2]] }]); const r = await preview(type, book)
    assert.equal(r.code, 200, `${type}: ${JSON.stringify(r.body)}`); assert.equal(r.body.allValid, true, `${type}: ${JSON.stringify(r.body.rows)}`); assert.equal(r.body.rows.length, 1) }
})
test('a user can fill the template (header + real rows) and the real preview accepts it; header spelling variants still map', async () => {
  const rows = { computers: [['PC-9', 1, 'TAG-9', 'SN-9', 'Intel i3', '8 GB', 128, 'gb', 'ssd', 'active', 'working', '']], equipment: [['Monitor', 1, '', 'EQ-9', 'EQSN-9', '', '', 'ACTIVE', 'WORKING', '']], users: [['2026-1111', 'Cruz', 'Ana', '', 'BSOA', 'Teacher', '']], laboratories: [['Lab Z', 20, 'OPEN', '', '', '', '']] }
  for (const type of TYPES) { const headers = SPECS[type].columns.map(c => c.header); const r = await preview(type, buildWorkbook([{ name: SPECS[type].dataSheet, rows: [headers, ...rows[type]] }]))
    assert.equal(r.code, 200, `${type} ${JSON.stringify(r.body)}`); assert.equal(r.body.allValid, true, `${type} ${JSON.stringify(r.body.rows)}`) }
})
test('missing required column gives a readable message naming the columns and pointing to the template', async () => {
  const headers = ['Computer Name', 'Laboratory ID', 'Processor']; const r = await preview('computers', buildWorkbook([{ name: 'Computers Template', rows: [headers, ['PC', 1, 'i5']] }]))
  assert.equal(r.code, 400); assert.match(r.body.message, /missing required columns: .*Asset Tag.*Serial Number/); assert.match(r.body.message, /header row/)
  const u = await preview('users', buildWorkbook([{ name: 'Sheet1', rows: [['ID Number', 'Surname'], ['1', 'X']] }])); assert.equal(u.code, 400); assert.match(u.body.message, /First Name, Role/)
  assert.deepEqual(missingColumns(['Laboratory Name'], 'laboratories'), ['Capacity'])
})
test('internal / database errors are never shown to the user (no SQL, codes, hosts or stack text)', async () => {
  dbMode = 'fail'; const book = buildWorkbook([{ name: 'Computers Template', rows: [SPECS.computers.columns.map(c => c.header), parseXlsx(buildTemplate('computers'))['Examples (not imported)'][2]] }])
  for (const type of TYPES) { const r = await preview(type, type === 'computers' ? book : buildWorkbook([{ name: SPECS[type].dataSheet, rows: [SPECS[type].columns.map(c => c.header), parseXlsx(buildTemplate(type))['Examples (not imported)'][2]] }]))
    assert.equal(r.code >= 400, true); assert.doesNotMatch(JSON.stringify(r.body), /ER_|SELECT|root|localhost|Access denied|at .*:\d+/i, type); assert.match(r.body.message, /Nothing was saved/) }
  dbMode = 'ok'
  assert.equal(userFacingMessage(new TypeError("Cannot read properties of undefined (reading 'x')")).includes('Cannot read'), false)
  assert.equal(userFacingMessage(new Error('The import is limited to 2000 rows per file.')), 'The import is limited to 2000 rows per file.')
})
test('template download handler: correct headers/file name and a readable .xlsx body; routes registered with the import roles', () => {
  for (const type of TYPES) { const r = res(); createImportTemplateController(type)({}, r); assert.equal(r.code, 200)
    assert.equal(r.headers['Content-Type'], 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'); assert.match(r.headers['Content-Disposition'], new RegExp(SPECS[type].fileName))
    assert.ok(Object.keys(parseXlsx(r.body)).length === 3) }
  const roles = {}; const rp = path.join(__dirname, '../middleware/roleAuth.js'); const mod = new Module(rp); mod.filename = rp; mod.loaded = true; let order = []
  mod.exports = { requireRole: (...r) => { order.push(r); return (q, s, n) => n() } }; const saved = require.cache[rp]; require.cache[rp] = mod
  for (const [file, type] of [['userRoutes', 'users'], ['laboratoryRoutes', 'laboratories'], ['computerRoutes', 'computers'], ['equipmentRoutes', 'equipment']]) { order = []; const f = path.join(__dirname, `../routes/${file}.js`); delete require.cache[f]; const router = require(f)
    const idx = router.stack.filter(l => l.route).findIndex(l => l.route.path === '/import-template' && l.route.methods.get); assert.ok(idx >= 0, `${file}: /import-template GET registered`)
    roles[type] = order[idx]; const routes = router.stack.filter(l => l.route).map(l => l.route.path); assert.ok(idx < routes.findIndex(p => p === '/:id' || p.startsWith('/:id')) || !routes.some(p => p === '/:id'), 'registered before /:id') }
  if (saved) require.cache[rp] = saved; else delete require.cache[rp]
  assert.deepEqual(roles.users, ['MIS']); assert.deepEqual(roles.laboratories, ['MIS']); assert.deepEqual(roles.computers, ['MIS', 'Inventory Staff']); assert.deepEqual(roles.equipment, ['MIS', 'Inventory Staff'])
})
